export default function TaskInterface({task, act}) {
  const [view, setView] = React.useState('overview');
  const [category, setCategory] = React.useState('All products');
  const [detail, setDetail] = React.useState('');
  const [showEvidence, setShowEvidence] = React.useState(false);
  const [showNext, setShowNext] = React.useState(false);
  const t = task || {};
  const locked = !!(t.progress || ['working','created','submitting'].includes(t.status) || t.receipt);
  const readable = value => typeof value === 'string' ? value : value == null ? '' : JSON.stringify(value);
  const fallbackScreens = [
    {id:'01M5R73654HJSZF2QC4Y5QM249',name:'Your next chapter, outside.'},
    {id:'01M5R73JCNC0VTZD9KFX97C1B4',name:'Your next chapter, outside.'},
    {id:'01M5R7450K8V6KV0CQVC6P06B5',name:'Your orders'},
    {id:'01M5R74KQ4DV6EJBNN6HJ0CMV2',name:'Shop the collection'},
    {id:'01M5R75K6KJV9GQXEY748RMH80',name:'Red running shoes'},
    {id:'01M5R76BET9J7EMGW1HCTYPADY',name:'Order ORD-1042'},
    {id:'01M5R76N3FJ9NQ9ZS6SQNJNSVW',name:'How can we help?'},
    {id:'01M5R76X7ACTHJEM1AF46912MV',name:'Returns and exchanges'}
  ];
  const fallbackFlows = [
    {name:'Returns, exchanges & warranty',exit:'01M5R73JCNC0VTZD9KFX97C1B4',note:'The recorded destination was the home screen, not the help topic.'},
    {name:'My orders',exit:'01M5R7450K8V6KV0CQVC6P06B5'},
    {name:'Black jacket',exit:'01M5R74KQ4DV6EJBNN6HJ0CMV2',note:'The recorded destination was the collection, not a jacket detail screen.'},
    {name:'View product & options →',exit:'01M5R75K6KJV9GQXEY748RMH80'},
    {name:'Footwear',exit:'01M5R74KQ4DV6EJBNN6HJ0CMV2',note:'The collection was reached; a filtered result is not established by this capture.'},
    {name:'Compare return methods and fees',exit:'01M5R76X7ACTHJEM1AF46912MV'},
    {name:'Browse the catalogue',exit:'01M5R74KQ4DV6EJBNN6HJ0CMV2'},
    {name:'View delivery timeline',exit:'01M5R775K02NKD2BE7AXPJ2RYM',note:'The flow record reports a reached screen, but its contents were not supplied. Shipment milestones remain unknown.'},
    {name:'Get returns or warranty help',exit:'01M5R76N3FJ9NQ9ZS6SQNJNSVW'},
    {name:'Review orders and delivery',exit:'01M5R76BET9J7EMGW1HCTYPADY'}
  ];
  const discovery = t.discovery || {};
  const screens = Array.isArray(discovery.screens) && discovery.screens.length ? discovery.screens : fallbackScreens;
  const flows = Array.isArray(discovery.flows) && discovery.flows.length ? discovery.flows : fallbackFlows;
  const products = [
    {name:'Red running shoes',category:'Footwear',text:'A lightweight everyday running shoe.',state:'Product screen captured',key:'shoes'},
    {name:'Black jacket',category:'Outerwear',text:'A weather-resistant shell with a removable hood.',state:'Collection listing captured · detail unverified',key:'jacket'},
    {name:'Trail day pack',category:'Equipment',text:'An 18-litre pack for day walks. Equipment has a separate warranty route.',state:'Collection listing captured · detail unvisited',key:'pack'}
  ];
  const navigate = next => { setView(next); setDetail(''); };
  const localButton = (label, next) => <button type="button" disabled={locked} onClick={() => setDetail(next)}>{label}</button>;
  const statusText = t.error ? 'Source or host error: ' + readable(t.error) : t.progress ? 'Host activity in progress. Local controls are paused.' : locked ? 'Host state is locked. This guide remains read-only.' : 'Read-only guide. Local browsing does not change the source.';
  return <div className="generated-root">
    <header className="generated-header"><div><strong>NORTHSTAR OUTFITTERS</strong><span className="generated-header-note">Observed site guide</span></div><span className="generated-badge">Read-only · synthetic records</span></header>
    <main className="generated-main">
      <section className="generated-intro"><p className="generated-eyebrow">Explore before choosing a task</p><h1>Your next chapter, outside.</h1><p className="generated-lead">Browse captured products, inspect order information, or find an aftercare topic. No task has been selected.</p></section>
      <div className="generated-status" role="status" aria-live="polite">{statusText}</div>
      <nav className="generated-nav" aria-label="Local site guide">{[['overview','Overview'],['shop','Shop'],['orders','My orders'],['help','Help centre']].map(([key,label]) => <button type="button" key={key} disabled={locked} aria-current={view === key ? 'page' : undefined} onClick={() => navigate(key)}>{label}</button>)}</nav>
      {view === 'overview' && <section aria-labelledby="generated-paths"><h2 id="generated-paths">Where would you like to look?</h2><div className="generated-grid">{[
        ['shop','Browsing','Shop the collection','Three product listings captured. The red running shoes detail screen was also reached.','Inspect products'],
        ['orders','Order information','Your orders','Two synthetic orders are listed. ORD-1042 has a captured detail screen.','Inspect orders'],
        ['help','Read-only help','How can we help?','Returns and exchanges, delivery, and equipment warranty are visible help topics.','Inspect help topics']
      ].map(([key,type,title,text,label]) => <section className="generated-card" key={key}><p className="generated-eyebrow">{type}</p><h3>{title}</h3><p>{text}</p><button type="button" disabled={locked} onClick={() => navigate(key)}>{label}</button></section>)}</div><p className="generated-caption">These are local views of captured evidence, not links to the merchant site.</p></section>}
      {view === 'shop' && <section aria-labelledby="generated-shop"><h2 id="generated-shop">Shop the collection</h2><label className="generated-filter" htmlFor="generated-category">Filter captured listings<select id="generated-category" value={category} disabled={locked} onChange={e => {setCategory(e.target.value); setDetail('');}}>{['All products','Footwear','Outerwear','Equipment'].map(x => <option key={x}>{x}</option>)}</select></label><p className="generated-caption">Local filter only. Source category navigation is not independently verified for every category.</p><div className="generated-grid">{products.filter(p => category === 'All products' || p.category === category).map(p => <section className="generated-card" key={p.key}><p className="generated-eyebrow">{p.category}</p><h3>{p.name}</h3><p>{p.text}</p><p className="generated-caption">{p.state}</p>{localButton('Inspect ' + p.name,p.key)}</section>)}</div>
        {detail === 'shoes' && <section className="generated-detail"><h3>Red running shoes · captured product details</h3><p>The source showed size 8 selected and available. Size 9 was described as sold out. These are captured source values, not choices made in this guide.</p><p>This storefront is a browsing sandbox. Checkout is not offered.</p><div className="generated-button-row">{localButton('Delivery and collection details','delivery')}{localButton('Returns and exchanges','returns')}</div></section>}
        {detail === 'jacket' && <section className="generated-detail"><h3>Black jacket · listing details</h3><p>The collection says the order contains Medium. The attempted Black jacket path reached “Shop the collection”; a dedicated jacket detail screen is unverified.</p></section>}
        {detail === 'pack' && <section className="generated-detail"><h3>Trail day pack · listing details</h3><p>The product detail link was observed but not visited in the supplied captures. Product options are unknown.</p>{localButton('Inspect equipment warranty link','warranty')}</section>}
      </section>}
      {view === 'orders' && <section aria-labelledby="generated-orders"><h2 id="generated-orders">Your orders</h2><p>Demo account · orders and eligibility are synthetic.</p><div className="generated-grid generated-two"><section className="generated-card"><p className="generated-eyebrow">Captured order detail</p><h3>ORD-1042</h3><p>Red shoes + Black jacket</p><p>Delivered · within the 30-day return window in the capture.</p>{localButton('Inspect ORD-1042','order1042')}</section><section className="generated-card"><p className="generated-eyebrow">Order list only</p><h3>ORD-0938</h3><p>Trail day pack</p><p>Delivered · outside the return window in the capture.</p>{localButton('Inspect captured listing','order0938')}</section></div>
        {detail === 'order1042' && <section className="generated-detail"><h3>Order ORD-1042</h3><p>Captured source: delivered, return window open, original payment card ending 4242.</p><ul><li>Red running shoes · size 8</li><li>Black jacket · Medium</li></ul><p>No items are selected for a transaction.</p><div className="generated-button-row">{localButton('View delivery timeline · evidence','timeline')}{localButton('Compare return methods & fees · evidence','returns')}</div><p className="generated-caption">A “Start a return →” source link was visible but was not followed. It is informational here, with no execution control.</p></section>}
        {detail === 'order0938' && <section className="generated-detail"><h3>ORD-0938 · captured listing</h3><p>Only the trail day pack listing and outside-return-window status are established. The order detail screen and any warranty eligibility decision remain unknown.</p>{localButton('Inspect equipment warranty link','warranty')}</section>}
        {detail === 'timeline' && <section className="generated-detail"><h3>View delivery timeline</h3><p>The flow record reports that a destination was reached, but its screen details are absent from the supplied evidence. Shipment milestones and dates are unknown.</p></section>}
      </section>}
      {view === 'help' && <section aria-labelledby="generated-help"><h2 id="generated-help">How can we help?</h2><div className="generated-grid">{[
        ['Returns & exchanges','Check methods, eligibility and fees','returns','Policy screen captured'],
        ['Delivery','Understand delivery and collection','delivery','Link observed · topic screen unvisited'],
        ['Equipment warranty','Find the right route for a damaged pack','warranty','Link observed · topic screen unvisited']
      ].map(([title,label,key,state]) => <section className="generated-card" key={key}><p className="generated-eyebrow">{state}</p><h3>{title}</h3>{localButton(label,key)}</section>)}</div></section>}
      {detail === 'returns' && <section className="generated-detail"><p className="generated-eyebrow">Captured policy · information only</p><h3>Returns and exchanges</h3><p>Eligible apparel and footwear may be returned within 30 days.</p><ul><li>Printed shipping label: a printer is required.</li><li>QR drop-off: no printer is required.</li><li>The source says to review the refund destination after changing a method; final merchant review is authoritative.</li></ul><p>Direct size exchanges are not supported in this sandbox. An eligible return is a separate request.</p><p className="generated-caption">No method or refund choice is being made. Current fees and refund amounts are not provided in this read-only guide.</p><div className="generated-button-row"><button type="button" disabled={locked} onClick={() => navigate('orders')}>Inspect orders</button>{localButton('Outside the return window? Warranty link','warranty')}</div></section>}
      {detail === 'delivery' && <section className="generated-detail"><h3>Delivery and collection</h3><p>This help link was observed on the product and help screens. The topic screen was not supplied; delivery terms, timings, and collection options remain unverified.</p></section>}
      {detail === 'warranty' && <section className="generated-detail"><h3>Equipment warranty</h3><p>The help centre offers “Find the right route for a damaged pack.” The warranty destination was not visited in the supplied captures. Coverage, requirements, and eligibility are unknown.</p><p>No claim can be started here.</p></section>}
      <section className="generated-records"><div className="generated-section-heading"><div><p className="generated-eyebrow">Evidence boundaries</p><h2>What was actually reached</h2></div><button type="button" disabled={locked} aria-expanded={showEvidence} aria-controls="generated-evidence" onClick={() => setShowEvidence(!showEvidence)}>{showEvidence ? 'Hide path records' : 'Inspect path records'}</button></div><p>Exploration was incomplete because its budget ran out. A verified flow record does not establish every step suggested by its name.</p>
        {showEvidence && <div id="generated-evidence"><div className="generated-notice"><h3>Source discrepancies</h3><ul><li>The “Returns, exchanges & warranty” path recorded the home screen as its destination.</li><li>The “Black jacket” path recorded the collection screen, not jacket details.</li><li>An earlier Help centre path broke. A later read-only overview did reach “How can we help?”; this does not verify every help link.</li><li>The delivery timeline has a reached-screen record, but its contents were not supplied.</li></ul></div><div className="generated-path-list">{flows.map((flow,index) => {const reachedId = flow.currentObservation && flow.currentObservation.reached || flow.exit; const reached = screens.find(s => s.id === reachedId); const known = fallbackFlows.find(f => f.name === flow.name); return <section className="generated-path" key={flow.id || index}><h3>{flow.name || 'Unnamed captured path'}</h3><p><strong>Recorded destination:</strong> {reached ? reached.name : 'Screen details unavailable · contents unknown'}</p>{(flow.note || known && known.note) && <p className="generated-caption">{flow.note || known.note}</p>}</section>;})}</div><section className="generated-notice"><h3>Other source findings</h3><p>The exploration reported contrast issues, an uncaught source exception, and a blocked external logging write during read-only inspection. Those findings remain open; this guide does not attempt to repair the source or contact external services.</p></section></div>}
      </section>
      <section className="generated-next"><p className="generated-eyebrow">Separate next step</p><h2>Want an interface for a specific task?</h2><p>This guide does not start or prepare transactions.</p><button type="button" disabled={locked} aria-expanded={showNext} aria-controls="generated-next-detail" onClick={() => setShowNext(!showNext)}>How to request a focused build</button>{showNext && <div id="generated-next-detail"><p>Use the host’s <strong>Build a focused interface</strong> control outside this guide, then explicitly state your task.</p><p>The supplied contract supports a separate task: “Return the red shoes, keep the jacket, refund original payment.” That task has not been selected or started here. Other transactions are not established as supported.</p></div>}</section>
      <footer className="generated-footer">Fictional merchant · Synthetic records only · No production access</footer>
    </main>
  </div>;
}
